  it('reports which booking caused the conflict', async () => {
    const first = await book(24, 25);
    const response = await book(24.5, 25.5, 'Overlap');
    expect(response.json().error.details.conflictingBookingId).toBe(first.json().id);
  });

  it('rejects a booking that fully engulfs an active booking', async () => {
    await book(24, 25);
    const response = await book(23, 26, 'Engulfing');
    expect(response.statusCode).toBe(409);
    expect(response.json().error.code).toBe('BOOKING_CONFLICT');
  });

  it('rejects a PATCH that moves a booking onto an occupied slot', async () => {
    await book(24, 25);
    const second = await book(30, 31, 'Movable');
    const response = await app.inject({
      method: 'PATCH',
      url: `/bookings/${second.json().id}`,
      payload: { startsAt: inHours(24.5), endsAt: inHours(25.5) },
    });
    expect(response.statusCode).toBe(409);
  });

  it('allows only one of two concurrent requests for the same slot to succeed', async () => {
    const [first, second] = await Promise.all([book(24, 25, 'A'), book(24, 25, 'B')]);
    const statusCodes = [first.statusCode, second.statusCode].sort();
    expect(statusCodes).toEqual([201, 409]);
  });

  describe('availability', () => {
    it('reports the whole range as free when there are no bookings', async () => {
      const response = await app.inject({
        method: 'GET',
        url: `/bookings/availability?roomId=${roomId}&from=${inHours(24)}&to=${inHours(28)}`,
      });
      expect(response.statusCode).toBe(200);
      expect(response.json().freeSlots).toHaveLength(1);
    });

    it('splits the range around an existing booking', async () => {
      await book(25, 26);
      const response = await app.inject({
        method: 'GET',
        url: `/bookings/availability?roomId=${roomId}&from=${inHours(24)}&to=${inHours(28)}`,
      });
      const slots = response.json().freeSlots;
      expect(slots).toHaveLength(2);
      expect(new Date(slots[0].endsAt).getTime()).toBe(new Date(inHours(25)).getTime());
      expect(new Date(slots[1].startsAt).getTime()).toBe(new Date(inHours(26)).getTime());
    });

    it('returns no free slots when the room is fully booked', async () => {
      await book(24, 28);
      const response = await app.inject({
        method: 'GET',
        url: `/bookings/availability?roomId=${roomId}&from=${inHours(24)}&to=${inHours(28)}`,
      });
      expect(response.json().freeSlots).toHaveLength(0);
    });

    it('rejects a range where `to` is not after `from`', async () => {
      const response = await app.inject({
        method: 'GET',
        url: `/bookings/availability?roomId=${roomId}&from=${inHours(28)}&to=${inHours(24)}`,
      });
      expect(response.statusCode).toBe(400);
    });
  });

  describe('batch create', () => {
    it('creates every booking when all slots are free', async () => {
      const response = await app.inject({
        method: 'POST',
        url: '/bookings/batch',
        payload: [
          { roomId, userId, title: 'One', startsAt: inHours(24), endsAt: inHours(25) },
          { roomId, userId, title: 'Two', startsAt: inHours(26), endsAt: inHours(27) },
        ],
      });
      expect(response.statusCode).toBe(200);
      const results = response.json();
      expect(results.every((result: { status: string }) => result.status === 'created')).toBe(true);
    });

    it('reports per-item conflicts without discarding the successful items', async () => {
      await book(24, 25);
      const response = await app.inject({
        method: 'POST',
        url: '/bookings/batch',
        payload: [
          { roomId, userId, title: 'Free', startsAt: inHours(26), endsAt: inHours(27) },
          { roomId, userId, title: 'Taken', startsAt: inHours(24.5), endsAt: inHours(25.5) },
        ],
      });
      const results = response.json();
      expect(results[0].status).toBe('created');
      expect(results[1].status).toBe('failed');
      expect(results[1].error.code).toBe('BOOKING_CONFLICT');
    });

    it('rejects an empty batch', async () => {
      const response = await app.inject({ method: 'POST', url: '/bookings/batch', payload: [] });
      expect(response.statusCode).toBe(400);
    });
  });
});

